import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { bundledSoundsDir } from '../../src/paths.js';
import { listBundledSounds, resolveSoundPath } from '../../src/sounds.js';

/** Minimal WAV reader — enough to check format and level. */
function readWav(file) {
  const buffer = fs.readFileSync(file);
  const samples = buffer.readUInt32LE(40) / 2;
  let peak = 0;
  let sumSquares = 0;
  for (let i = 0; i < samples; i += 1) {
    const sample = buffer.readInt16LE(44 + i * 2) / 32768;
    peak = Math.max(peak, Math.abs(sample));
    sumSquares += sample * sample;
  }
  return {
    riff: buffer.toString('ascii', 0, 4),
    wave: buffer.toString('ascii', 8, 12),
    channels: buffer.readUInt16LE(22),
    rate: buffer.readUInt32LE(24),
    bits: buffer.readUInt16LE(34),
    seconds: samples / buffer.readUInt32LE(24),
    peak,
    rms: Math.sqrt(sumSquares / samples)
  };
}

test('every bundled sound is a valid 44.1kHz 16-bit mono WAV', () => {
  const sounds = listBundledSounds();
  assert.ok(sounds.length >= 6);

  for (const sound of sounds) {
    const wav = readWav(resolveSoundPath(sound));
    assert.equal(wav.riff, 'RIFF', `${sound.id} RIFF header`);
    assert.equal(wav.wave, 'WAVE', `${sound.id} WAVE header`);
    assert.equal(wav.channels, 1, `${sound.id} is mono`);
    assert.equal(wav.rate, 44100, `${sound.id} sample rate`);
    assert.equal(wav.bits, 16, `${sound.id} bit depth`);
  }
});

test('bundled sounds are peak-normalised to a consistent level', () => {
  // Regression: hand-tuned gains drifted so far apart that `blip` played at
  // -18 dBFS and was effectively inaudible, while task-complete was 3.7x louder.
  const levels = listBundledSounds().map((sound) => ({
    id: sound.id,
    ...readWav(resolveSoundPath(sound))
  }));

  for (const level of levels) {
    assert.ok(
      Math.abs(level.peak - 0.75) < 0.01,
      `${level.id} peaks at ${level.peak.toFixed(3)}, expected ~0.75`
    );
  }

  const peaks = levels.map((level) => level.peak);
  assert.ok(
    Math.max(...peaks) - Math.min(...peaks) < 0.02,
    'no bundled sound is noticeably louder than another'
  );
});

test('bundled sounds are long enough to be noticed and short enough not to annoy', () => {
  for (const sound of listBundledSounds()) {
    const wav = readWav(resolveSoundPath(sound));
    assert.ok(wav.seconds >= 0.15, `${sound.id} lasts ${wav.seconds.toFixed(2)}s — too brief to hear`);
    assert.ok(wav.seconds <= 2, `${sound.id} lasts ${wav.seconds.toFixed(2)}s — too long for a hook`);
    assert.ok(wav.rms > 0.01, `${sound.id} carries real signal, not near-silence`);
  }
});

test('the generator reproduces the committed files exactly', async () => {
  // Proves the bundled audio is generated, not sourced from anywhere else.
  // Only the generated WAVs at the top level; the directory may also hold
  // sub-folders of sounds added by hand, which the generator does not own.
  const before = fs
    .readdirSync(bundledSoundsDir, { withFileTypes: true })
    .filter((entry) => entry.isFile() && entry.name.endsWith('.wav'))
    .map((entry) => ({
      name: entry.name,
      bytes: fs.readFileSync(path.join(bundledSoundsDir, entry.name))
    }));

  const { execFileSync } = await import('node:child_process');
  execFileSync(process.execPath, ['scripts/gen-sounds.js'], {
    cwd: path.resolve(bundledSoundsDir, '..', '..'),
    stdio: 'ignore'
  });

  for (const original of before) {
    const now = fs.readFileSync(path.join(bundledSoundsDir, original.name));
    assert.ok(now.equals(original.bytes), `${original.name} regenerated byte-identically`);
  }
});
